// Gives each demo candidate (seed-demo-via-api.js) a resume PDF and an intro
// video, so the swipe card shows the first resume page and an "Intro video"
// player. The files are generated by a small helper outside the repo; this
// script uploads them to Cloudinary (the same unsigned preset the app uses)
// and saves the URLs on the profiles through the public API.
//
//   MEDIA_DIR=/path/with/resume-<i>.pdf+intro-<i>.mp4 \
//   SEED_STATE_FILE=/path/to/.demo-accounts.json \
//   node scripts/attach-demo-media.js
//
// Safe to re-run: it just uploads again and overwrites the two URLs.

const fs = require("node:fs");
const path = require("node:path");
const { CANDIDATES } = require("./seed-demo-candidates");
const { api, must, emailOf, profileBody } = require("./seed-demo-via-api");

const MEDIA_DIR = process.env.MEDIA_DIR;
const STATE_FILE = process.env.SEED_STATE_FILE || path.join(__dirname, ".demo-accounts.json");
const CLOUD = process.env.CLOUDINARY_CLOUD_NAME || "osmuzyat";
const PRESET = process.env.CLOUDINARY_UPLOAD_PRESET || "twp0ykep";

if (!MEDIA_DIR) {
  console.error("Set MEDIA_DIR to the folder with resume-<index>.pdf and intro-<index>.mp4");
  process.exit(1);
}
const state = JSON.parse(fs.readFileSync(STATE_FILE, "utf8"));
const log = (...a) => console.log(new Date().toISOString().slice(11, 19), ...a);

async function upload(kind, file, filename) {
  const form = new FormData();
  form.append("upload_preset", PRESET);
  form.append("file", new Blob([fs.readFileSync(file)]), filename);
  const res = await fetch(`https://api.cloudinary.com/v1_1/${CLOUD}/${kind}/upload`, { method: "POST", body: form });
  const json = await res.json().catch(() => ({}));
  if (!res.ok || !json.secure_url) {
    throw new Error(`cloudinary ${kind} ${res.status}: ${JSON.stringify(json.error || json).slice(0, 160)}`);
  }
  return json.secure_url;
}

(async () => {
  let done = 0;
  for (const [index, row] of CANDIDATES.entries()) {
    const name = row[0];
    try {
      const account = state.accounts.find((a) => a.email === emailOf(row));
      if (!account) {
        log(`skip ${name}: not in the state file`);
        continue;
      }
      const resume = path.join(MEDIA_DIR, `resume-${index}.pdf`);
      const video = path.join(MEDIA_DIR, `intro-${index}.mp4`);
      const login = must(await api("POST", "/auth/login", { body: { email: account.email, password: account.password } }), `login ${name}`);
      const resumeUrl = await upload("raw", resume, `${name.replace(/\W+/g, "-")}-resume.pdf`);
      const introVideoUrl = await upload("video", video, `${name.replace(/\W+/g, "-")}-intro.mp4`);
      const { body } = profileBody(row, index);
      must(
        await api("PUT", "/candidates/me/profile", { token: login.token, body: { ...body, resumeUrl, introVideoUrl } }),
        `profile ${name}`,
      );
      done++;
      log(`media attached (${done}): ${name}`);
    } catch (e) {
      log(`FAILED ${name}: ${e.message}`);
    }
  }
  log(`done. ${done}/${CANDIDATES.length} candidates now have a resume and an intro video`);
})();
